from pathlib import Path
import sqlite3,json,hashlib
from decimal import Decimal
R=Path.cwd();P=R/'docs/fundamental-data-engine/evidence/2026-10-28-b1-public-opening-linkage'
sha=lambda b:hashlib.sha256(b).hexdigest()
load=lambda p:json.loads(p.read_text())
sources=load(P/'PUBLIC_SOURCES.json'); bysource={x['ticker']:x for x in sources}
old=R/'docs/fundamental-data-engine/evidence/2026-10-26-m8-identity-bridge-evidence-preparation/IDENTITY_BRIDGE_CANDIDATES.json'
dossiers=load(old)['evidenceDossiers'];statementPath=R/'docs/fundamental-data-engine/evidence/2026-10-28-b1-owner-statement-review/REVIEW.json';statement=load(statementPath)
byStmt={x['tickerAsPrinted']:x for x in statement['observations']['positions']}
c=sqlite3.connect('file:data/vn30.sqlite?mode=ro',uri=True);c.row_factory=sqlite3.Row
sid='BROKER_SNAPSHOT:cc46785ff2d4f7477911d0cb7dad6ee38b872b5cc6a8566a78683637fdf43852'
s=c.execute('select * from broker_observation where id=?',(sid,)).fetchone();assert s and sha(s['body'].encode())==s['body_hash']; snap=json.loads(s['body']);rows=[]
for x in dossiers:
 t=x['ledgerSecurityId'];m=x['market'];pub=bysource[t];assert pub['sourcePageOpened'];assert m['isin'] in pub['pageExcerpt'] and 'HOSE' in pub['pageExcerpt'];assert 'phổ thông' in pub['pageExcerpt'] or 'Common' in pub['pageExcerpt']
 indices=[i for i,p in enumerate(snap['positions']) if p['symbol']==t or (t=='FPT' and p['symbol']=='FPT_UNAVAILABLE')]
 positions=[snap['positions'][i] for i in indices]; openingQty=sum(Decimal(p['quantity']) for p in positions)
 st=[byStmt[t]]+([byStmt['FPT_WFT']] if t=='FPT' else []);statementQty=sum(Decimal(p['quantity']) for p in st)
 ledger=c.execute('select id,event_at,facts from ledger_transaction where id=?',('tcbs-personal-v1:opening:'+t,)).fetchone();lf=json.loads(ledger['facts'])['facts'];assert lf['source']['reference']==sid+':'+t and lf['opening']['evidence']==sid
 observations=[]
 for a in x['historicalTCBSIdentities']:
  ref=a['evidence']['reference'];oid=ref.split('#broker_observation/id/',1)[1];r=c.execute('select * from broker_observation where id=?',(oid,)).fetchone();assert r and sha(r['body'].encode())==r['body_hash']==a['evidence']['sha256']
  body=json.loads(r['body']);cell=body
  for part in a['evidence']['pointer'].strip('/').split('/'):cell=cell[int(part)] if isinstance(cell,list) else cell[part]
  # Verify independently against actual source payload, not just dossier summary.
  assert cell['symbol']==t and cell['isinCode']==m['isin'] and str(cell['codeId'])==m['providerInstrumentCode']
  observations.append({'observationId':oid,'sha256':r['body_hash'],'receivedAt':r['received_at'],'jsonPointer':a['evidence']['pointer'],'isin':a['isin'],'providerInstrumentCode':a['codeId']})
 assert observations and openingQty==statementQty==Decimal(lf['quantity'])
 rows.append({'ticker':t,'isin':m['isin'],'exchange':'HOSE','securityClass':'COMMON_SHARE','publicSourceUrl':pub['url'],'provider':'TCBS','providerInstrumentCode':m['providerInstrumentCode'],'openingSnapshotId':sid,'openingPositionPointers':['/positions/'+str(i) for i in indices],'openingPositions':positions,'openingLedgerId':ledger['id'],'openingLedgerFactsSha256':sha(ledger['facts'].encode()),'openingEventAt':ledger['event_at'],'statementDate':'2026-10-26','statementPage':1,'statementRows':st,'openingQuantity':str(openingQty),'statementQuantity':str(statementQty),'quantityMatches':True,'historicalMarketObservations':observations,'linkageStatus':'TECHNICALLY_CORROBORATED_NOT_INDEPENDENTLY_ACCEPTED','continuousAccountHistoryProven':False})
result={'schemaVersion':'b1-public-opening-linkage-v1','reviewDate':'2026-10-28','scope':'Owner-authorized public identity and opening-record technical comparison','sourcePolicy':'Public security identity HTML only; no financial PDF acquisition','openingReceivedAt':s['received_at'],'holdingsAsOf':snap['holdingsAsOf'],'sourceSnapshotSha256':s['body_hash'],'inputPins':{'dossierSha256':sha(old.read_bytes()),'statementReviewSha256':sha(statementPath.read_bytes())},'holdings':rows,'ownerClarification':{'receivedDate':'2026-10-28','source':'Owner message in current conversation','symbol':'FPT_WFT','underlyingTicker':'FPT','quantity':'20','nature':'BONUS_SHARES_OWNER_CONFIRMED','tradable':False,'creditDate':None,'tradableFrom':None,'instruction':'Record as owned; reclassify only when conversion to tradable confirmed. Never add another 20.','historicalAlias':'FPT_UNAVAILABLE','aliasLinkageBasis':'Owner clarification plus two dated source observations; not an independently authenticated corporate-action witness'},'status':{'publicIdentityComparison':'COMPLETE_11_OF_11','openingSnapshotLedgerStatementComparison':'COMPLETE_11_OF_11','formalB1':'OPEN_FORMAL_ACCEPTANCE_AND_ACCOUNT_CONTINUITY_UNPROVEN','missingInstrumentCodes':False,'independentAcceptance':False,'effectiveOrKnownIntervalAssigned':False,'databaseChanged':False,'runtimeMappingActivated':False},'limitations':['Public announcements establish issuer/security reference facts, not private account ownership or uninterrupted holding history.','Matching quantities corroborate already-selected ticker identities; equality is not used to discover identity.','Public sources reviewed now are not backdated as known on October 8.','TCBS observations retain actual capture clocks; no inferred legal effective interval.','No complete transaction/status evidence through October 23 is established by endpoint comparison.','Prior source authenticity/account-perimeter/reviewer gates are not silently waived.']}
(P/'LINKAGE_REVIEW.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
lines=['# B1 — đối chiếu nguồn công khai và snapshot mở đầu','', 'Ngày kiểm tra: 28/10/2026. **Hoàn thành đối chiếu kỹ thuật 11/11 mã; chưa phải chấp thuận độc lập B1 cho production.**','', 'Đã đọc trực tiếp SQLite ở chế độ read-only; kiểm tra SHA-256 snapshot và các phản hồi TCBS lịch sử; truy cập nguồn VSDC công khai. Không lấy số lượng bằng nhau làm căn cứ tạo danh tính. Ticker/ISIN và loại/sàn được kiểm tra trước; số lượng chỉ là phép đối chiếu sau đó.','', '| Mã | ISIN | Sàn / loại | SL 08/10 | SL 26/10 | Nguồn VSDC |','|---|---|---|---:|---:|---|']
for r in rows:lines.append(f"| {r['ticker']} | {r['isin']} | HOSE / phổ thông | {r['openingQuantity']} | {r['statementQuantity']} | [Nguồn]({r['publicSourceUrl']}) |")
lines+=['','## Liên kết lịch sử','',f"Snapshot gốc có hash hợp lệ, receivedAt `{s['received_at']}`, holdingsAsOf `{snap['holdingsAsOf']}`. Mỗi dòng có JSON Pointer, liên kết source của bút toán mở đầu và các phản hồi TCBS lịch sử đã kiểm hash trong LINKAGE_REVIEW.json. Bút toán FPT gộp 220, nhưng snapshot gốc giữ 200 giao dịch + 20 chưa khả dụng. Không sửa bút toán hoặc coi cả 220 được giao dịch.",'','Sao kê 26/10 có FPT 200 giao dịch + FPT_WFT 20 chờ giao dịch. Chủ tài khoản xác nhận 20 là cổ phiếu thưởng đang sở hữu, chưa giao dịch; chưa có ngày chuyển giao dịch. Ghi nhận làm rõ này riêng, không cộng thêm 20 và không áp ngày chuyển giả định. VPL dùng thông báo VSDC chuyển sang HOSE hiệu lực 09/05/2025; không dùng hoán đổi năm 2011 để chứng minh vị thế hiện tại.','','## Trạng thái B1 và phần còn thiếu','','Đã giải quyết phần tra cứu ISIN/mã TCBS/sàn/loại của 11 mã và truy xuất liên kết nội bộ về snapshot 08/10. Không cần yêu cầu chủ tài khoản xin lại các mã này. Các nguồn công khai được đọc ngày 28/10, không gán thành hệ thống đã biết ngày 08/10.','','B1 chính thức vẫn mở theo hợp đồng hiện hành: chưa có chứng cứ xác thực độc lập về account/subaccount/phạm vi, liên kết account→instrument và lịch sử liên tục trong khoảng 08–23/10, cùng quyết định reviewer đúng phạm vi. Hai mốc số lượng khớp nhau không chứng minh không có giao dịch giữa kỳ. Không coi báo cáo này là thay đổi chính sách hoặc chấp thuận độc lập.','','Không đổi DB, source seals, runtime adapter, NAV, scoring hoặc release. B2–B7 không thay đổi. Không lưu số tài khoản/CCCD/tên chủ tài khoản/đường dẫn riêng tư trong gói này.']
(P/'REVIEW.md').write_text('\n'.join(lines)+'\n')
(P/'VERIFICATION.json').write_text(json.dumps({'reviewDate':'2026-10-28','snapshotHashVerified':True,'publicIdentityMatches':len(rows),'openingLedgerStatementMatches':len(rows),'historicalMarketPayloadsVerified':sum(len(r['historicalMarketObservations']) for r in rows),'fptSplitPreserved':True,'sqliteMode':'ro','independentAcceptance':False},indent=2)+'\n')
print('Verified',len(rows),'identities and opening links;',sum(len(r['historicalMarketObservations']) for r in rows),'historical market witnesses.')
